   $body.='<form method="post" action="/?action=edit_user">'.inputCsrf().'<input type="hidden" name="id" value="'.$id.'"><div class="formgrid"><label>Nome<input name="first_name" value="'.C::h($person['first_name']).'" required></label><label>Cognome<input name="last_name" value="'.C::h($person['last_name']).'" required></label><label>Email<input name="email" type="email" value="'.C::h($person['email']).'" required></label></div><button class="subtle">Salva account</button></form>';
   $body.='<h3>Impianti consentiti</h3><div class="plant-list">';foreach($plants as $plant)if((int)$plant['company_id']===(int)$person['company_id']){$has=isset($allowed[$id][(int)$plant['id']]);$body.='<form method="post" action="/?action='.($has?'revoke_plant':'grant_plant').'">'.inputCsrf().'<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="plant_id" value="'.$plant['id'].'"><span>'.C::h($plant['name']).'</span><button class="subtle">'.($has?'Rimuovi accesso':'Concedi accesso').'</button></form>';}$body.='</div>';
   $body.='<form method="post" action="/?action=reset_user_password">'.inputCsrf().'<input type="hidden" name="id" value="'.$id.'"><label>Nuova password iniziale<input type="password" name="new_password" minlength="12" required></label><button class="subtle">Reimposta password</button></form></details>';
  }$body.='</section>';
 }
 if($tab==='events'&&$u['role']==='admin'){$events=C::all('SELECT e.*,d.title,u.first_name,u.last_name,u.email,c.name company,p.name plant FROM download_events e JOIN documents d ON d.id=e.document_id JOIN users u ON u.id=e.user_id JOIN companies c ON c.id=d.company_id JOIN plants p ON p.id=d.plant_id ORDER BY e.started_at DESC LIMIT 300');$body.='<section class="card"><h2>Download registrati</h2><p>La data indica l’avvio della trasmissione dal server, non la conferma del salvataggio sul dispositivo.</p><div class="scroll"><table><thead><tr><th>Documento</th><th>Persona</th><th>Azienda / impianto</th><th>Data e ora (Italia)</th></tr></thead><tbody>';foreach($events as $e)$body.='<tr><td>'.C::h($e['title']).'</td><td>'.C::h($e['first_name'].' '.$e['last_name']).'<small>'.C::h($e['email']).'</small></td><td>'.C::h($e['company'].' / '.$e['plant']).'</td><td>'.C::date($e['started_at']).'</td></tr>';$body.='</tbody></table></div></section>';}
 if($tab==='archive'&&$u['role']==='admin'){
  $files=C::all('SELECT d.id,d.title,d.bytes,d.created_at,d.deleted_at,u.first_name,u.last_name,c.name company FROM documents d JOIN users u ON u.id=d.recipient_id JOIN companies c ON c.id=d.company_id ORDER BY d.created_at DESC LIMIT 500');
  $used=(int)C::row('SELECT COALESCE(SUM(bytes),0) n FROM documents WHERE deleted_at IS NULL')['n'];
  $body.='<section class="card"><h2>Archivio file</h2><p>File attivi: '.number_format($used/1073741824,2,',','.').' GiB. La soglia email è 2 GiB residui, quando la quota è configurata.</p><form method="post" action="/?action=bulk_delete" onsubmit="return confirm(\'Eliminare i documenti selezionati? I clienti perderanno accesso e i file verranno rimossi.\')">'.inputCsrf().'<div class="scroll"><table><thead><tr><th>Seleziona</th><th>Documento</th><th>Destinatario</th><th>Data</th><th>Dimensione</th></tr></thead><tbody>';
  foreach($files as $f)$body.='<tr><td>'.($f['deleted_at']?'—':'<input type="checkbox" name="ids[]" value="'.$f['id'].'" aria-label="Seleziona '.C::h($f['title']).'">').'</td><td>'.C::h($f['title']).($f['deleted_at']?' <small>Eliminato</small>':'').'</td><td>'.C::h($f['first_name'].' '.$f['last_name'].' · '.$f['company']).'</td><td>'.C::date($f['created_at']).'</td><td>'.number_format($f['bytes']/1048576,1,',','.').' MB</td></tr>';
  if(!$files)$body.='<tr><td colspan="5">Nessun file.</td></tr>';
  $body.='</tbody></table></div><button class="danger">Elimina selezionati</button></form></section>';
 }
